-- Real LPS professor seed crawled from khctnv.ftu.edu.vn + law.ftu.edu.vn (36 professors)
-- Safe to re-run (idempotent upsert on school_id+slug).

delete from public.professors where slug in ('nguyen-van-a','tran-thi-b','le-van-c','pham-thi-d');

insert into public.professors (school_id, faculty_id, slug, full_name, academic_title, bio, research_interests, source_status)
select s.id, f.id, v.slug, v.full_name, v.title, v.bio, '{}'::text[], 'seed'
from public.schools s
join public.faculties f on f.school_id = s.id and f.slug = 'lps'
join (values
    ('than-thi-hanh', 'Thân Thị Hạnh', 'TS', 'Chuyên ngành đào tạo Triết học/Lịch sử Triết học. Cô tốt nghiệp cử nhân tại trường Đại học sư phạm Hà Nội năm 2008; Nhận bằng thạc sĩ tại Học viện Chính trị Quốc gia Hồ Chí Minh năm 2011 và bảo vệ thành công Luận án tiến sĩ đạt loại xuất sắc tại Học viện Khoa học xã hội năm 2018; Là thành viên của Tổ chức Khoa học và Chuyên gia Việt Nam toàn cầu (AVSE Global), Hội Triết học Việt Nam. Năm 2019 cô được giao nhiệm vụ Phó Trưởng khoa, phụ trách khoa Lý luận chính trị và đến năm 2021, cô được bổ nhiệm Trưởng khoa Khoa Lý luận chính trị (từ tháng 09/2023 đổi tên thành Khoa Khoa học Chính trị và Nhân văn) của trường ĐH Ngoại Thương. Các lĩnh vực nghiên cứu mà cô đang theo đuổi đã đạt được thành tựu như: Lịch sử tư tưởng Việt Nam, Văn hóa phương Đông, Lịch sử triết học, Phát triển nguồn nhân lực, Giáo dục đại học.'),
    ('vu-thi-que-anh', 'Vũ Thị Quế Anh', 'TS', 'Tốt nghiệp thạc sỹ chuyên ngành Kinh tế chính trị (2003) và tiến sỹ chuyên ngành Kinh tế thế giới & quan hệ kinh tế quốc tế (2014), Cô có nhiều năm gắn bó với trường Đại học Ngoại thương. Cô được sinh viên đánh giá cao về chuyên môn, sự thân thiện, nhiệt huyết và hướng dẫn họ những kỹ năng cần thiết để thành công.'),
    ('nguyen-thi-to-uyen', 'Nguyễn Thị Tố Uyên', 'TS', 'Tốt nghiệp Ths tại ĐH KHXH&NV- ĐHQGHN năm 2008. Bảo vệ thành công luận án TS ngành Chính trị học năm 2021 tại Khoa Khoa học chính trị, ĐHKHXH&NV, ĐHQGHN. Từ khi tốt nghiệp Đại học, cô đã về công tác, giảng dạy tại Trường Đại học Ngoại thương. Với lòng nhiệt huyết, yêu nghề của mình, cô luôn là...'),
    ('tran-huy-quang', 'Trần Huy Quang', 'ThS', 'Thầy tốt nghiệp thạc sỹ tại Trường Đại học Khoa học xã hội và nhân văn năm 2008 và đang là Nghiên cứu sinh ngành Triết học của Trường Đại học Khoa học xã hội và nhân văn. Hiện thầy là Chi ủy viên, Chủ tịch Công đoàn Khoa Lý luận chính trị, và là giảng viên môn Triết học, thuộc Bộ môn Những nguyên lý cơ bản của chủ nghĩa Mác - Lênin. Với lòng nhiệt huyết, sự thân thiện, chuyên môn tốt và tích cực đổi mới phương pháp giảng dạy, thầy luôn được sinh viên yêu mến và đánh giá cao.'),
    ('phan-thanh-huong', 'Phan Thanh Hương', 'ThS', 'Chức danh: Thư ký Khoa Chuyên môn: Tốt nghiệp Thạc sĩ ngành Quản lý Giáo dục tại Trường Đại học Giáo dục, ĐHQGHN.'),
    ('tran-thi-thom', 'Trần Thị Thơm', 'ThS', 'Tốt nghiệp Cử nhân Chính trị học – Sư phạm Triết học tại Đại học Sư phạm Hà Nội năm 2013; Tốt nghiệp Thạc sĩ ngành Triết học tại Đại học Sư phạm Hà Nội năm 2016. Cô có kinh nghiệm làm việc ở các đơn vị công lập và ngoài công lập từ khi tốt nghiệp đại học đến tháng 11 năm 2022 cô công tác tại bộ môn Triết học và Chính trị học thuộc Khoa Khoa học Chính trị và Nhân văn, Trường Đại học Ngoại thương.'),
    ('ngo-thi-nhu', 'Ngô Thị Như', 'TS', 'Tốt nghiệp Thạc sĩ năm 2009 tại ĐH KHXH&NV – ĐHQG Tp. HCM. Bảo vệ thành công Luận án Tiến sĩ chuyên ngành Lịch sử Triết học năm 2013 tại ĐH KHXH&NV – ĐHQG Tp. HCM. Hiện nay, cô Ngô Thị Như đang giảng dạy học phần “Tư duy logic và PPNC”. Đồng thời, cô cũng rất tích cực hướng dẫn các nhóm sinh viên tham gia cuộc thi “Sinh viên nghiên cứu khoa học” nhiều năm gần đây tại Trường Đại học Ngoại thương.'),
    ('duong-duc-dai', 'Dương Đức Đại', 'TS', 'Cử nhân Kinh tế chính trị, Khoa Kinh tế - Đại học Quốc gia Hà Nội (2006); Thạc sỹ Kinh tế chính trị, Trường Đại học Kinh tế - Đại học Quốc gia Hà Nội (2010); Thạc sỹ Nghiên cứu phát triển (Development Research), International Institute of Social Studies, Netherlands (2011); Thạc sỹ Kinh tế, Đại học Missouri Thành phố Kansas, bang Missouri, Hoa Kỳ (2016); Tiến sỹ ngành Kinh tế và Khoa học xã hội tại Đại học Missouri Thành phố Kansas, bang Missouri, Hoa Kỳ (2020). Môn học giảng dạy: Kinh tế chính trị Mác - Lênin, Những nguyên lý cơ bản của chủ nghĩa Mác - Lênin, Lịch sử các học thuyết kinh tế, Geopolitics.'),
    ('dao-thi-nhung', 'Đào Thị Nhung', 'ThS', 'Tốt nghiệp Thạc sỹ chuyên ngành Triết học tại trường Đại học Sư phạm Hà Nội (2014). Hiện Cô đang là Nghiên cứu sinh chuyên ngành Chính trị học tại trường Đại học Khoa học Xã hội và Nhân văn, Đại học Quốc gia Hà Nội. Cô là giảng viên môn Chủ nghĩa xã hội khoa học thuộc bộ môn Triết học và Chính trị học. Các lĩnh vực nghiên cứu chính: Triết học, chủ nghĩa xã hội khoa học, Chính trị học.'),
    ('nguyen-mai-phuong', 'Nguyễn Mai Phương', 'TS', 'Chuyên ngành đào tạo Lịch sử Đảng, Tư tưởng Hồ Chí Minh. Năm 2010, bảo vệ thành công luận văn thạc sĩ tại Đại học Quốc gia Hà Nội. Năm 2014, bảo vệ thành công luận án tiến sĩ tại Trường Đại học Khoa học Xã hội và Nhân văn, Đại học Quốc gia Hà Nội. Với kiến thức chuyên môn tốt cùng với lòng nhiệt huyết, tận tâm với nghề, cô được nhiều thế hệ học trò đánh giá cao về chuyên môn và yêu mến.'),
    ('dinh-thi-quynh-ha', 'Đinh Thị Quỳnh Hà', 'ThS', '2000: Tốt nghiệp Đại học Ngoại thương, chuyên ngành Kinh tế đối ngoại; 2009: Thạc sĩ Kinh tế, Đại học Quốc gia Hà Nội; 2023: Thạc sĩ Tâm lí học, Đại học Sư phạm Hà Nội; Các lĩnh vực quan tâm: Giáo dục & đào tạo, kinh tế, chính trị, xã hội học, tâm lí học, di cư, bình đẳng giới...'),
    ('dao-thi-trang', 'Đào Thị Trang', 'TS', 'Tốt nghiệp Ths tại Trung tâm Đào tạo – Bồi dưỡng giảng viên Lý luận chính trị- Đại Học Quốc Gia Hà Nội năm 2011. Bảo vệ thành công Luận án TS ngành Triết học năm 2018 tại Khoa Triết học, Học viện Báo chí và Tuyên truyền. Từ khi tốt nghiệp Đại học, cô đã về công tác, giảng dạy tại Trường Đại học Ngoại thương. Với tình yêu nghề và lòng nhiệt huyết cô luôm sẵn sàng đồng hành cùng các em.'),
    ('nguyen-thi-tung-lam', 'Nguyễn Thị Tùng Lâm', 'TS', 'Giảng viên Nguyễn Thị Tùng Lâm nhận bằng Tiến sĩ Triết học năm 2022 tại Học viện KHXH, Viện Hàn Lâm Khoa học Việt Nam. Cô Tùng Lâm trở thành thành viên của mái nhà Ngoại thương sau khi tốt nghiệp tại Đại học KHXH&NV. Mối quan tâm hiện tại của Cô liên quan đến phát triển nguồn nhân lực được nghiên cứu dưới nhiều khía cạnh khác nhau của Triết học.'),
    ('hoang-van-vinh', 'Hoàng Văn Vinh', 'ThS', 'Tốt nghiệp Th.S chuyên ngành Kinh tế chính trị tại Trung tâm đào tạo, bồi dưỡng giảng viên Lý luận chính trị - Đại học Quốc gia Hà Nội năm 2013. Năm 2014, thầy đã về công tác, giảng dạy tại trường Đại học Ngoại thương.'),
    ('nguyen-thu-hai', 'Nguyễn Thu Hải', 'TS', 'Tiến sĩ Lịch sử Đảng Tốt nghiệp trường ĐH KHXHNV'),
    ('dang-huong-giang', 'Đặng Hương Giang', 'ThS', 'Tốt nghiệp cử nhân năm 2001, chuyên ngành Kinh tế đối ngoại, Trường ĐH Ngoại thương. Nhận bằng Thạc sĩ năm 2011, Trường Đại học Quốc gia, năm 2011. Công tác giảng dạy tại Đại học Ngoại thương từ năm 2002. TRƯỜNG ĐẠI HỌC NGOẠI THƯƠNG ___________________________________________________ Khoa học Chính trị và Nhân văn - Trường Đại học Ngoại thương ___________________________________________________ Địa chỉ: Phòng B203 (tầng 2, nhà B), 91 Chùa Láng, Đống Đa, Hà Nội ___________________________________________________ SĐT: 84-4-3835 6800 (ext: 595, 596) ___________________________________________________ Khoa học Chính trị & Nhân văn Kinh tế chính trị quốc tế Kinh tế chính trị quốc tế &copy; Copyright @ 2023 Khoa Khoa học Chính trị và Nhân văn. Designed by Trung tâm CNTT. window.gtranslateSettings = /* document.write */ window.gtranslateSettings || {};window.gtranslateSettings[''17726848''] = {"default_language":"vi","languages":["en","vi"],"url_structure":"none","'),
    ('nguyen-thi-mo', 'Nguyễn Thị Mơ', 'GS.TS', 'GS. TS. Nguyễn Thị Mơ GS. TS. NGND. Nguyễn Thị Mơ Tốt nghiệp Đại học Luật và nhận bằng Cử nhân ngành Luật học, chuyên ngành Tư pháp quốc tế, tại Trường Quan hệ Quốc tế (MGIMO), Mátxcơva (Liên Xô cũ) vào tháng 7 năm 1974. Về giảng dạy Luật tại Trường Đại học Ngoại Thương tháng 9 năm 1974. Nghiên cứu sinh tại Khoa Luật trường Đại học Tổng hợp Lômônôxốp (MGU) và nhận bằng Tiến sỹ Luật học tại trường Đại học Tổng hợp Lômônôxốp (MGU), Mátxcơva (Liên Xô cũ) năm 1984. Thành tích nổi bật: -Nhận bằng sau đại học của Trường Kinh doanh Châu Âu (thuộc Phòng Thương mại Quốc tế-ICC) về kinh tế thị trường năm 1991. -Là Trọng tài Viên Trung tâm trong tài Quôc tế Việt Nam (VIAC) từ năm 1993. -Được phong Chức danh Phó Giáo sư ngành Luật học năm 1996 (tại Việt Nam), được phong Giáo sư ngành Luật học năm 2003 (tại Việt Nam). Được tặng Danh hiệu Nhà giáo Ưu tú năm 1998, Nhà giáo Nhân dân năm 2006. -Cô nguyên là Hiệu trưởng Trường Đại học Ngoại thương (1998-2005), Tổng biên tập Tạp chí Kinh tế đối ngoại (2002-2011) và đã từng giữ chức vụ Trưởng Bộ môn Luật thuộc khoa Quản trị kinh doanh. Hiện nay, cô đang là Giảng viên cao cấp Khoa Luật tại trường Đại học Ngoại thương và là Trọng tài viên rất uy tín của Trung tâm trọng tài Quốc tế Việt Nam (VIAC). Lĩnh vực nghiên cứu chuyên môn của cô là Tư pháp quốc tế. Cô đã và đang giảng dạy các môn học cho chương trình cử nhân, như: Pháp luật đại cương, Pháp luật kinh tế, Pháp luật trong hoạt động Kinh tế đối ngoại, Pháp luật Đầu tư, Pháp luật Doanh nghiệp, Pháp luật thương mại quốc tế và cho chương trình cao học, như: Pháp luật thương mại quốc tế, Pháp luật về hợp đồng và giải quyết tranh chấp trong thương mại quốc tế, Các định chế thương mại quốc tế (Chương trình thạc sĩ kinh tế tại Đại học Ngoại thương) và các môn: Pháp Luật về hợp đồng kinh doanh, Ph'),
    ('bui-ngoc-son', 'Bùi Ngọc Sơn', 'PGS.TS', 'GS. TS. Bùi Ngọc Sơn PGS.TS Bùi Ngọc Sơn Giảng viên Khoa Luật ĐH Ngoại Thương, tốt nghiệp Đại học Ngoại thương năm 1983, tốt nghiệp đại học chuyên ngành Kinh tế quốc tế tại Học viện Ngoại thương Liên Xô năm 1993, cử nhân Luật Kinh tế năm 1998, nhận bằng thạc sỹ kinh tế và tiến sỹ kinh tế tại ĐH Ngoại Thương năm 1999 và 2003. Thành tích nổi bật -Thầy hiện là Phó Hiệu trưởng trường ĐH Ngoại Thương và đồng thời là Trọng tài viên Trung tâm Trọng tại Quốc tế Việt Nam bên cạnh Phòng Thương Mại và Công nghiệp Việt Nam – VIAC. PGS, TS Bùi Ngọc Sơn luôn được các thế hệ sinh viên ĐH Ngoại Thương đánh giá cao về sự nghiêm túc, nhiệt tình, chuyên môn sâu và phương pháp giảng dạy hiệu quả, hiện đại. Thầy là chủ nhiệm 3 đề tài nhánh cấp Nhà nước và rất nhiều đề tài nghiên cứu Khoa học cấp Bộ, đề tài nghiên cứu Khoa học cấp thành phố, cấp trường. PGS,TS Bùi Ngọc Sơn là chủ biên và đồng tác giả của nhiều sách giáo trình và sách tham khảo trong lĩnh vực Luật và Kinh tế như Giáo trình Luật Thương mại quốc tế (NXB Tư pháp); Giáo trình Pháp luật doanh nghiệp, Giáo trình Pháp luật kinh doanh quốc tế; đã viết và công bố gần 30 bài báo khoa học trên các tạp chí có uy tín. Các sách chuyên khảo: Năng lực xuất khẩu của doanh nghiệp Việt Nam trong điều kiện kinh tế thị trường (Nhà xuất bản Thông tin và Truyền thông); Nâng cao năng lực xuất khẩu nhóm hàng nông lâm thủy sản của Việt Nam sang thị trường Nhật Bản (NXB Đại học quốc gia Hà Nội -2011)…Hướng dẫn viết luận án tiến sỹ, luận văn cao học …'),
    ('tang-van-nghia', 'Tăng Văn Nghĩa', 'PGS.TS', 'GS. TS. Tăng Văn Nghĩa PGS, TS Tăng Văn Nghĩa Giảng viên Khoa Luật, Trường ĐHNT, tốt nghiệp Trường Đại học Luật Hà Nội năm 1991, đào tạo thạc sĩ và tiến sĩ tại CHLB Đức (trường Đại học Tổng hợp Goettingen). Thầy vừa là trưởng bộ môn pháp luật cơ sở, vừa là trưởng Khoa Sau đại học trường Đại học Ngoại thương. Thầy hiện tham gia giảng dạy các môn học như Pháp luật cạnh tranh, Pháp lý đại cương, Pháp luật kinh doanh quốc tế, Pháp luật đầu tư cho bậc đào tạo đại học và sau đại học. Thầy cũng là chuyên gia trong nhiều dự án của MUTRAP, chủ nhiệm đề tài nghị định thư cấp Nhà nước và chủ nhiệm nhiều đề tài nghiên cứu Khoa học cấp Bộ trong những năm vừa qua. PGS, TS Tăng Văn Nghĩa là chủ biên và đồng tác giả của nhiều sách giáo trình và sách tham khảo trong lĩnh vực luật, đặc biệt là Luật Cạnh tranh (bằng tiếng Việt và tiếng Đức) và có nhiều bài báo đăng trên tạp chí chuyên ngành. Thầy cũng tham gia tích cực tham gia các chương trình nghiên cứu, các khóa học ngắn hạn, các chương trình trao đổi giảng viên tại nước ngoài, như tại CHLB Đức, Vương Quốc Anh, Nhật Bản, Thụy Sĩ…'),
    ('ho-thuy-ngoc', 'Hồ Thúy Ngọc', 'PGS.TS', 'GS. TS. Hồ Thúy Ngọc PGS.TS Hồ Thúy Ngọc Bà Hồ Thúy Ngọc là trưởng bộ môn Pháp luật Thương mại quốc tế, trưởng khoa Đào tạo quốc tế, trường Đại học Ngoại thương. Bà đồng thời là trọng tài viên Trung tâm Trọng tài quốc tế Việt Nam từ năm 2011. Với 15 năm kinh nghiệm giảng dạy, nghiên cứu trong các lĩnh vực hợp đồng và sở hữu trí tuệ, 10 năm tư vấn cho doanh nghiệp trong các vụ tranh chấp quốc tế liên quan tới đầu tư, mua bán hàng hóa và sở hữu trí tuệ, bà trở thành thành viên của Hiệp hội quốc tế về thương mại ngũ cốc và thức ăn gia súc với trụ sở chính tại London (Vương quốc Anh) đầu năm 2021.'),
    ('nguyen-minh-hang', 'Nguyễn Minh Hằng', 'PGS.TS', 'GS. TS. Nguyễn Minh Hằng PGS.TS Nguyễn Minh Hằng Tốt nghiệp Đại học Ngoại Thương loại giỏi, nhận bằng thạc sỹ Luật Kinh doanh quốc tế loại tốt và bảo vệ luận án tiến sỹ Luật kinh doanh quốc tế đạt loại xuất sắc tại trường Đại học Tours (Cộng hòa Pháp). Hiện nay Cô đang đảm nhận vị trí Trưởng Khoa Luật của Đại học Ngoại Thương, đồng thời là Giám đốc Trung tâm nghiên cứu và thực hành pháp luật (trực thuộc Khoa Luật), trọng tài viên Trung tâm trọng tài quốc tế Việt Nam VIAC. Cô là một giảng viên nhiều kinh nghiệm giảng dạy và nghiên cứu, say sưa và tâm huyết với nghề. Cô đã có hơn 10 năm kinh nghiệm giảng dạy các môn học như Pháp luật kinh doanh quốc tế, Pháp luật doanh nghiệp, Pháp luật đầu tư, Giải quyết tranh chấp… Cô đã chủ trì/tham gia nhiều đề tài nghiên cứu các cấp, tham gia và chủ biên nhiều sách, giáo trình và có nhiều bài viết đăng trên các tạp chí có uy tín trong nước và quốc tế. Cô còn là thành viên của Nhóm nghiên cứu về Hợp đồng quốc tế của Cộng hòa Pháp, thành viên của Hiệp hội Luật so sánh của Pháp, cộng tác viên cho Báo Diễn đàn doanh nghiệp (chuyên mục Pháp luật Kinh doanh), chuyên gia tư vấn tại nhiều công ty luật, chuyên gia nghiên cứu của Phòng Thương mại và Công nghiệp Việt Nam (VCCI), Trung tâm trọng tại quốc tế Việt Nam (VIAC), Bộ Công Thương, Bộ Tư pháp. Đặc biệt, Cô còn rất tích cực hỗ trợ và dành nhiều tâm huyết cho hoạt động của các Câu lạc bộ của sinh viên như CLB Nhà tư vấn Luật, CLB Sinh viên NCKH./.'),
    ('vo-sy-manh', 'Võ Sỹ Mạnh', 'TS', 'TS. Võ Sỹ Mạnh TS. Võ Sỹ Mạnh Tốt nghiệp cử nhân 2 trường Đại học: Cử nhân Kinh tế ngoại thương – Trường Đại học Ngoại thương, Việt Nam năm 2004 và Cử nhân Luật - Trường Đại học Luật Hà Nội, Việt Nam năm 2007. Năm 2008, thầy bắt đầu tham gia khóa đào tạo Thạc sỹ Luật Thương mại Quốc tế thuộc Đại học Leicester, Vương Quốc Anh và đã tốt nghiệp năm 2009. Bên cạnh đó, thầy đã hoàn thành Khóa Đào tạo nghiệp vụ luật sư tại Học viện Tư pháp và hiện đang là chuyên gia tư vấn tại Công ty Luật số 5 - Quốc gia, một trong những công ty luật hàng đầu ở Việt Nam. Với công tác chuyên môn, thầy vừa tham gia giảng dạy vừa tư vấn (tiềng Việt và tiếng Anh) các vấn đề pháp luật khác nhau, đặc biệt các vấn đề liên quan đến kinh doanh quốc tế, hợp đồng thương mại, doanh nghiệp. Bên cạnh đó, thầy còn là Giám đốc Trung tâm Đảm bảo Chất lượng, Trường Đại học Ngoại thương.'),
    ('nguyen-lan-anh', 'Nguyễn Lan Anh', 'ThS', 'Thạc sỹ Nguyễn Lan Anh Tốt nghiệp cử nhân Luật Kinh tế - Trường Đại học Luật Hà nội năm 2002. Sau đó cô tiếp tục viết và bảo vệ thạc sỹ luật học, chuyên sâu về Luật thương mại với đề tài về pháp luật cạnh tranh tại Khoa luật – Đại học Tổng hợp Potsdam, Cộng hòa Liên bang Đức năm 2006. Ngay sau khi tốt nghiệp thạc sỹ tại Cộng hòa Liên bang Đức, cô trở thành giảng viên bộ môn Luật – Khoa Quản trị kinh doanh – Đại học Ngoại thương từ năm 2006 cho đến nay. Các môn học hiện nay cô đang đảm trách gồm Pháp lý đại cương, Pháp luật tài chính – ngân hàng, Pháp luật dân sự và tố tụng dân sự, Pháp luật cạnh tranh. Và hiện nay Cô đang là nghiên cứu sinh chuyên ngành Luật kinh tế tại Đại học Luật Hà Nội. Phương pháp giảng dạy của cô đối với sinh viên là tạo cảm hứng cho sinh viên thông qua các bài giảng có nội dung thực tế để lôi cuốn và tạo không khí thảo luận sôi nổi trong lớp học. Thông qua các cuộc điều tra đánh giá từ phía sinh viên, cô luôn được đánh giá cao về kiến thức chuyên môn cũng như phương pháp sư phạm trong giảng dạy.'),
    ('dang-thi-minh-ngoc', 'Đặng Thị Minh Ngọc', null, 'Giảng viên Đặng Thị Minh Ngọc Tốt nghiệp cử nhân 2 trường Đại học Ngoại thương và Đại học Luật Hà Nội. Cô cũng đã hoàn thành khóa Đào tạo luật sư tại Học viện Tư pháp. Hiện nay, cô đang tham gia khóa đào tạo thạc sĩ chuyên ngành Luật Kinh tế tại trường Đại học Luật Hà Nội. Là một giảng viên giỏi về chuyên môn, và nhiệt tình trong công tác giảng dạy, cô luôn được nhiều thế hệ sinh viên yêu mến và đánh giá cao về chất lượng bài giảng cũng như sự tâm huyết với nghề. Bên cạnh đó, cô còn là một giáo viên rất tích cực trong công tác nghiên cứu khoa học, và từng hướng dẫn sinh viên nghiên cứu khoa học đạt giải khuyến khích cấp Bộ.'),
    ('mai-minh-huong', 'Mai Minh Hương', 'ThS', 'Thạc sỹ Mai Minh Hương Tốt nghiệp cử nhân Quản trị Kinh doanh trường Đại học Ngoại Thương năm 2007 và nhận bằng thạc sỹ luật về Luật thương mại quốc tế năm 2010 tại Đại học Aberdeen (Vương quốc Anh). Hiện nay cô đang tham gia giảng dạy một số môn học như Pháp luật trong hoạt động kinh tế đối ngoại, Pháp luật doanh nghiệp… Cô cũng tham gia giảng dạy một số môn Luật bằng tiếng anh cho chương trình chất lượng cao của ĐH Ngoại Thương, chương trình liên kết giữa ĐH Ngoại Thương và ĐH Niels Brock Đan Mạch và chương trình tiên tiến giữa ĐH Ngoại Thương và ĐH Corolado State University Hoa Kỳ. Cô cũng tham gia tích cực vào hoạt động nghiên cứu khoa học cũng như các khóa học, hội thảo trong và ngoài nước. Ngoài công tác giảng dạy và nghiên cứu khoa học, cô còn hỗ trợ các hoạt động ngoại khóa của sinh viên ĐH Ngoại Thương như dạ hội Chúng tôi Quản trị kinh doanh, chương trình We are Managers, cuộc thi Mr. & Miss FBA, giải bóng đá B.A League…'),
    ('ha-cong-anh-bao', 'Hà Công Anh Bảo', 'ThS', 'Thạc sỹ Hà Công Anh Bảo Tốt nghiệp thạc sỹ tại trường đại học Wales (Vương quốc Anh) năm 2010. Thầy đang là Nghiên cứu sinh ngành quản trị kinh doanh của Đại học Ngoại Thương Hà Nội. Hiện thầy đang là thành viên của chương trình đào tạo chuyên gia tư vấn cho doanh nghiệp xuất khẩu của Trung tâm xúc tiến nhập khẩu từ các nước đang phát triển của Hà Lan (CBI), và là một trong những thành viên tham gia thành lập trung tâm tư vấn cho doanh nghiệp vừa và nhỏ (LECO) của trường Đại học Ngoại thương. Với lòng nhiệt huyết của mình, thầy được sinh viên đánh giá cao về sự thân thiện, chuyên môn và đổi mới phương pháp giảng dạy đem lại hiệu quả cho người học.'),
    ('nguyen-minh-thu', 'Nguyễn Minh Thư', 'ThS', 'Thạc sỹ Nguyễn Minh Thư , Tốt nghiệp thạc sỹ Luật – Trường Đại học Luật Hà Nội năm 2010. Hiện nay cô đang là Nghiên cứu sinh chuyên ngành luật Dân sự tại trường Đại học Luật Hà Nội và theo dự kiến sẽ hoàn thành và bảo vệ luận án tiến sỹ vào năm 2013. Hiện nay, cô đang phụ trách giảng dạy các môn học Pháp lý đại cương, Pháp luật tố tụng dân sự, Pháp luật dân sự, Pháp luật Hình sự. Bên cạnh đó, cô còn là tư vấn viên trung tâm tư vấn pháp luật cho doanh nghiệp vừa và nhỏ LECO. Là người được đào tạo chuyên sâu về luật nên cô cũng là một trong những giảng viên được đánh giá cao về kiến thức chuyên môn và phong cách giảng daỵ trẻ trung, nhiệt tình.'),
    ('phung-thi-yen', 'Phùng Thị Yến', 'ThS', 'Thạc sỹ Phùng Thị Yến T ốt nghiệp thạc sỹ chuyên ngành Luật kinh tế tại Viện Nhà nước và Pháp luật năm 2011. Trước khi bước vào nghề giáo, cô đã có hơn 2 năm kinh nghiệm làm chuyên viên tư vấn pháp lý tại một văn phòng luật sư uy tín. Bên cạnh đó, cô còn tích lũy được rất nhiều kiến thức thực tiễn qua một thời gian dài công tác tại Tòa án nhân dân, tham gia tiến hành các thủ tục tố tụng trong rất nhiều vụ việc. Lĩnh vực giảng dạy chuyên môn của cô tại Khoa Luật, trường Đại học Ngoại thương là pháp lý đại cương và pháp luật về Sở hữu trí tuệ. Ngoài cương vị là một giáo viên, cô còn là tư vấn viên của trung tâm tư vấn pháp lý cho doanh nghiệp vừa và nhỏ LECO. Mặc dù mới tham gia vào công tác giảng dạy nhưng cô đã thu hút được sự chú ý của sinh viên bởi lòng nhiệt tình và những bài giảng có kết hợp kiến thức chuyên môn với những ví dụ thực tiễn vô cùng lý thú.'),
    ('nguyen-thi-huyen', 'Nguyễn Thị Huyền', 'ThS', 'Tốt nghiệp thạc sỹ chuyên ngành Luật Dân sự Trường đại học Luật Hà Nội năm 2006. Đồng thời, cô cũng hoàn thành Khoá đào tạo Luật sư tại Học Viện Tư Pháp. Là một người ham học hỏi, tâm huyết với nghề, yêu quý sinh viên, Cô luôn phấn đấu trở thành một giảng viên được đồng nghiệp tín nhiệm và sinh viên yêu mến. Hiện nay cô đang được phân công giảng dạy môn Pháp luật đại cương và Pháp luật đất đai – môi trường.'),
    ('nguyen-hoang-my-linh', 'Nguyễn Hoàng Mỹ Linh', null, 'Giảng viên Nguyễn Hoàng Mỹ Linh Tốt nghiệp trường Đại học Luật Hà Nội năm 2009. Cô là giảng viên Khoa Luật – trường Đại học Ngoại thương và hiện đang phụ trách giảng dạy các môn học Pháp lý đại cương, Pháp luật về Thuế, Pháp luật Sở hữu trí tuệ. Bên cạnh đó, cô còn là tư vấn viên trung tâm tư vấn pháp luật cho doanh nghiệp vừa và nhỏ LECO. Ngoài việc giảng dạy, cô còn tích cực tham gia một số công trình nghiên cứu Luật học cấp Bộ, cấp trường để tự nâng cao kiến thức chuyên môn. Hiện nay Cô đang tham gia khóa đào tạo thạc sỹ chuyên ngành Luật Kinh tế tại trường Đại học Luật Hà Nội. Là người được đào tạo chuyên sâu trong lĩnh vực khoa học pháp lý, cùng với lòng nhiệt tình, say mê, tâm huyết trong công việc, kết hợp với phương thức giảng dạy tiến bộ và sáng tạo nên cô cũng là một trong những giảng viên được đánh giá cao về kiến thức chuyên môn và phong cách giảng dạy trẻ trung, nhiệt tình.'),
    ('dao-xuan-thuy', 'Đào Xuân Thủy', null, 'Giảng viên Đào Xuân Thủy Tốt nghiệp cử nhân Luật Kinh doanh Quốc tế, trường Đại học Ngoại thương. Hiện nay, thầy đang tham gia giảng dạy các môn Pháp luật Hải quan, Pháp luật trong hoạt động kinh tế đối ngoại, Pháp luật đại cương, Pháp luật kinh tế. Là một giáo viên giỏi về chuyên môn và sự nghiêm túc trong nghiên cứu khoa học, thầy được các đồng nghiệp và sinh viên đánh giá rất cao.'),
    ('hoang-thi-minh-hang', 'Hoàng Thị Minh Hằng', 'ThS', 'Thạc sỹ Hoàng Thị Minh Hằng Tốt nghiệp cử nhân Luật Kinh doanh Quốc tế, Đại học Ngoại thương Hà Nội. Năm 2012, cô hoàn thành chương trình Thạc sỹ Luật và Kinh tế Quốc tế tại Viện Thương mại Thế giới (WTI), Đại học Bern, Thụy Sỹ. Là một giáo viên được đánh giá cao về chuyên môn, về sự nhiệt tình với công việc và lòng hăng say với nghề, cô đã truyền cảm hứng cho rất nhiều thế hệ sinh viên niềm yêu thích đối với môn Luật thông qua những bài giảng của mình. Hiện nay cô đang tham gia giảng dạy cả tiếng Anh và tiếng Việt đối với các môn học: Pháp luật đại cương, Pháp luật Tài chính Ngân hàng.'),
    ('vu-kim-ngan', 'Vũ Kim Ngân', 'ThS', 'Thạc sỹ Vũ Kim Ngân Cử nhân Quản trị Kinh doanh chuyên ngành Luật Kinh doanh quốc tế tại Đại học Ngoại Thương Hà Nội (2008), tốt nghiệp Thạc sỹ Luật Kinh tế quốc tế tại Học viện Thương mại Thế giới WTI, trường Đại học Bern, Thụy Sỹ (2011). Hiện nay, cô Ngân đang làm việc tại Tổ chức Thương mại thế giới WTO tại thành phố Geneva, Thụy Sỹ. Chuyên môn giảng dạy và lĩnh vực nghiên cứu của cô gắn liền với pháp luật thương mại quốc tế và luật của WTO liên quan đến thương mại hàng hóa, thương mại dịch vụ và giải quyết tranh chấp. Năm 2011, cô Ngân tham gia viết một chương về Giải quyết tranh chấp trong thương mại quốc tế trong giáo trình Pháp luật thương mại quốc tế của trường Đại học Ngoại Thương do Nhà xuất bản Lao Động ấn hành'),
    ('tran-thi-lien-huong', 'Trần Thị Liên Hương', null, 'Giảng viên Trần Thị Liên Hương Tốt nghiệp Cử nhân Luật Kinh doanh Quốc tế trường Đại học Ngoại thương và hiện đang tham gia chương trình đào tạo Thạc sỹ Kinh tế tại Học viện Khoa học Xã hội (Thuộc Viện Khoa học Xã hội Việt Nam). Cô đã để lại những ấn tượng sâu sắc trong lòng sinh viên bởi sự nhiệt tình, tận tâm với học trò và bởi những bài giảng vô cùng thú vị. Ngoài công tác giảng dạy, cô còn là thành viên của Trung tâm tư vấn pháp lý cho doanh nghiệp vừa và nhỏ LECO.'),
    ('do-viet-anh-thai', 'Đỗ Viết Anh Thái', 'ThS', 'Thạc sỹ Đỗ Viết Anh Thái Là giảng viên trẻ nhất vừa gia nhập khoa Luật năm 2011. Cô là cựu sinh viên K45 của Trường Đại học Ngoại thương, thủ khoa đầu vào (khối D3) và thủ khoa đầu ra của trường Đại học Ngoại Thương niên khóa 2006 -2010. Trong quá trình học tập tại Đại học Ngoại thương, cô đã tích cực tham gia các hoạt động dành cho sinh viên và đạt được nhiều thành tích xuất sắc như : Giải nhất cuộc thi Sinh viên nghiên cứu khoa học Trường Đại học Ngoại thương với chủ đề Pháp luật về phá sản, Giải nhất cuộc thi Khởi nghiệp cùng Kawai, Giải nhất cuộc thi Dynamique của Tổ chức Đại học Pháp ngữ … Sau khi tốt nghiệp thạc sỹ Đại học Lyon 3 (Pháp), sự gắn bó với môi trường giảng dạy, nghiên cứu và niềm đam mê với môn Luật đã thôi thúc cô trở về cống hiến cho Trường Đại học Ngoại thương và chính thức trở thành giảng viên tập sự của Khoa Luật kể từ tháng 12/2011. Hiện nay cô đang theo học chương trình Thạc sĩ Luật kinh doanh tại Trường Đại học Paris 2.'),
    ('nguyen-thi-lan', 'Nguyễn Thị Lan', 'ThS', 'Thạc sỹ Nguyễn Thị Lan Là giảng viên trở thành thành viên của Khoa Luật năm 2012. Cô tốt nghiệp cử nhân Luật tại trường Đại học Luật Hà Nội năm 2010. Với sự ham mê học hỏi, sau khi tốt nghiệp cử nhân, Cô vừa là thành viên tư vấn Luật tại một Văn phòng Luật sư tại Hà Nội, Cô vừa tham gia chương trình đào tạo Thạc sỹ tại Trường Đại học Luật Hà Nội và tốt nghiệp năm 2012. Lòng ham mê và mong muốn được giảng dạy pháp luật đã thôi thúc Cô trở thành giảng viên, và Cô chính thức trở thành giảng viên tập sự của Khoa Luật từ tháng 9 năm 2012. Cô cũng đã hoàn thành khoá đào tạo Luật sư tại Học viện tư pháp từ năm 2011')
  ) as v(slug, full_name, title, bio) on true
where s.slug = 'ftu'
on conflict (school_id, slug) do update set
  full_name = excluded.full_name,
  academic_title = excluded.academic_title,
  bio = excluded.bio;